            <div class="force-options">${At.map((e,t)=>`<button class="force-option ${t===0?`selected`:``}" type="button" data-force="${e}" aria-pressed="${t===0}"><span class="force-index">0${t+1}</span>${e}<i aria-hidden="true">${t===0?`●`:`○`}</i></button>`).join(``)}</div>
